import{_ as e,o as r,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"理解AI","description":"","frontmatter":{},"headers":[],"relativePath":"ai-dive/understand_AI.md","filePath":"ai-dive/understand_AI.md","lastUpdated":null}'),i={name:"ai-dive/understand_AI.md"};function o(h,a,l,d,s,p){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="理解ai" tabindex="-1">理解AI <a class="header-anchor" href="#理解ai" aria-label="Permalink to &quot;理解AI&quot;">​</a></h1><h2 id="境界" tabindex="-1">境界 <a class="header-anchor" href="#境界" aria-label="Permalink to &quot;境界&quot;">​</a></h2><h3 id="知其然境界" tabindex="-1">知其然境界 <a class="header-anchor" href="#知其然境界" aria-label="Permalink to &quot;知其然境界&quot;">​</a></h3><p>第一个是知其然，也叫知其所以然境界，知道当下的人工智能到底是什么，知道机器学习和深度学习大概是个什么东西，不会过分的去神话AI，知道目前AI的优势，更知道目前AI的局限，如果你从事相关产品经理或者做相关领域投资，达到第一境界即可。</p><p>名词词条：<a href="https://hyper.ai/wiki" target="_blank" rel="noreferrer">https://hyper.ai/wiki</a></p><h3 id="应用者境界" tabindex="-1">应用者境界 <a class="header-anchor" href="#应用者境界" aria-label="Permalink to &quot;应用者境界&quot;">​</a></h3><p>应用者境界是大部分人工智能算法工程师所在的境界，主要就是明白算法原理，知道如何实现，核心在于知道如何把他应用在一个实际的业务场景之中，如果你是一个利用AI来解决业务问题的算法工程师，那么你至少需要达到这个境界。</p><h3 id="工程师境界" tabindex="-1">工程师境界 <a class="header-anchor" href="#工程师境界" aria-label="Permalink to &quot;工程师境界&quot;">​</a></h3><p>工程师境界也是很难的一种境界，需要用很强的理论背景和工程实现能力，能独立复现最新的论文，深刻理解论文的实现原理，并能在上面做一些小创新。如果你想成为更牛逼的AI算法工程师，那么就需要达到这个境界。</p><h3 id="科学家境界" tabindex="-1">科学家境界 <a class="header-anchor" href="#科学家境界" aria-label="Permalink to &quot;科学家境界&quot;">​</a></h3><p>科学家境界是很少很少一部分人能达到的境界，主要是那些从事人工智能研究的科学家，他们能原创出很多的算法和理论，解决一些最前沿的难题。比如深度学习的鼻祖Hinton,生成对抗网络发明人 Ian goodfellow,Xgboost发明人陈天奇等等。</p><h2 id="各个学习方法" tabindex="-1">各个学习方法 <a class="header-anchor" href="#各个学习方法" aria-label="Permalink to &quot;各个学习方法&quot;">​</a></h2><h3 id="无监督学习方法的模型、策略、算法" tabindex="-1">无监督学习方法的模型、策略、算法 <a class="header-anchor" href="#无监督学习方法的模型、策略、算法" aria-label="Permalink to &quot;无监督学习方法的模型、策略、算法&quot;">​</a></h3><p>无监督学习用于聚类、降维、话题分析、图分析。<a href="https://www.bobinsun.cn/ai/2019/07/02/Unsupervised-Learning/" target="_blank" rel="noreferrer">2</a></p><h3 id="有监督学习" tabindex="-1">有监督学习 <a class="header-anchor" href="#有监督学习" aria-label="Permalink to &quot;有监督学习&quot;">​</a></h3><p>10 种监督学习方法特点的总结概括 <a href="https://www.bobinsun.cn/ai/2019/07/02/10-Supervised-learning-methods/" target="_blank" rel="noreferrer">3</a></p><h2 id="应用" tabindex="-1">应用 <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用&quot;">​</a></h2><p>AI目前主要的应用领域有3个方向，包括：计算机视觉、语音交互、自然语言处理。<a href="https://zhuanlan.zhihu.com/p/384020411" target="_blank" rel="noreferrer">4</a></p>',18)])])}const b=e(i,[["render",o]]);export{u as __pageData,b as default};
